                for (var i = 0; i < mine.Length; i++) if (!comparer.Equals(mine[i], theirs[i])) return false;
            }
            else
                for (var i = 0; i < mine.Length; i++) if (!comparer.Equals(mine[i], other.Get(at + offset + i))) return false;
